import java.util.*;

class Solution {
  public boolean splitArray(int[] nums) {
    int n = nums.length;
    if (n < 7) return false;
    int[] pre = new int[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
    // fix the middle cut j; collect equal-sum splits of the left part, then look for one on the right
    for (int j = 3; j < n - 3; j++) {
      Set<Integer> left = new HashSet<>();
      for (int i = 1; i < j - 1; i++) if (pre[i] == pre[j] - pre[i + 1]) left.add(pre[i]);
      for (int k = j + 2; k < n - 1; k++) {
        int part = pre[k] - pre[j + 1];
        if (part == pre[n] - pre[k + 1] && left.contains(part)) return true;
      }
    }
    return false;
  }
}
